--
-- Table structure for table `course_enrollments`
--

CREATE TABLE `course_enrollments` (
  `enrollment_id` bigint(20) NOT NULL,
  `tenant_id` int(11) NOT NULL,
  `course_id` int(11) NOT NULL,
  `last_lesson_id` bigint(20) DEFAULT NULL,
  `last_accessed_at` datetime DEFAULT NULL,
  `attempts` int(11) DEFAULT NULL,
  `user_id` int(11) NOT NULL,
  `status` enum('not_started','in_progress','completed','dropped') COLLATE utf8mb4_unicode_ci DEFAULT 'not_started',
  `progress_percentage` decimal(5,2) DEFAULT '0.00',
  `final_score` decimal(5,2) DEFAULT NULL,
  `time_spent_minutes` int(11) DEFAULT '0',
  `enrollment_source` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT 'Direct Assignment',
  `enrolled_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `started_at` datetime DEFAULT NULL,
  `is_mandatory` tinyint(1) DEFAULT '1',
  `is_started` tinyint(1) DEFAULT '0',
  `is_completed` tinyint(1) DEFAULT '0',
  `completed_at` datetime DEFAULT NULL,
  `assigned_by` int(11) DEFAULT NULL,
  `last_activity_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `due_date` date DEFAULT NULL,
  `is_active` tinyint(1) DEFAULT '1',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

