--
-- Triggers `learning_path_items`
--
DELIMITER $$
CREATE TRIGGER `trg_update_path_item_count_insert` AFTER INSERT ON `learning_path_items` FOR EACH ROW BEGIN
    UPDATE learning_paths
    SET
        total_items = (SELECT COUNT(*) FROM learning_path_items WHERE path_id = NEW.path_id AND is_active = 1),
        total_courses = (SELECT COUNT(*) FROM learning_path_items WHERE path_id = NEW.path_id AND item_type = 'course' AND is_active = 1),
        total_assessments = (SELECT COUNT(*) FROM learning_path_items WHERE path_id = NEW.path_id AND item_type = 'assessment' AND is_active = 1),
        updated_at = NOW()
    WHERE path_id = NEW.path_id;

    IF NEW.section_id IS NOT NULL THEN
        UPDATE learning_path_sections
        SET total_items = (SELECT COUNT(*) FROM learning_path_items WHERE section_id = NEW.section_id AND is_active = 1)
        WHERE section_id = NEW.section_id;
    END IF;
END
$$
DELIMITER ;

