--
-- Triggers `learning_path_reviews`
--
DELIMITER $$
CREATE TRIGGER `trg_update_path_rating` AFTER INSERT ON `learning_path_reviews` FOR EACH ROW BEGIN
    IF NEW.status = 'approved' THEN
        UPDATE learning_paths
        SET
            avg_rating = (SELECT AVG(rating) FROM learning_path_reviews WHERE path_id = NEW.path_id AND status = 'approved'),
            total_ratings = (SELECT COUNT(*) FROM learning_path_reviews WHERE path_id = NEW.path_id AND status = 'approved')
        WHERE path_id = NEW.path_id;
    END IF;
END
$$
DELIMITER ;

