--
-- Table structure for table `proc_assessment_questions`
--

CREATE TABLE `proc_assessment_questions` (
  `assessment_question_id` bigint(20) UNSIGNED NOT NULL,
  `assessment_id` bigint(20) UNSIGNED NOT NULL,
  `section_id` bigint(20) UNSIGNED DEFAULT NULL,
  `question_id` bigint(20) UNSIGNED NOT NULL,
  `tenant_id` bigint(20) UNSIGNED NOT NULL,
  `points_override` decimal(10,2) DEFAULT NULL,
  `time_limit_override` int(11) DEFAULT NULL COMMENT 'Seconds',
  `required` tinyint(1) DEFAULT '0' COMMENT 'Must be answered',
  `sort_order` int(11) DEFAULT '0',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

--
-- Triggers `proc_assessment_questions`
--
DELIMITER $$
CREATE TRIGGER `trg_aq_check_manual` AFTER INSERT ON `proc_assessment_questions` FOR EACH ROW BEGIN
    DECLARE has_manual INT;

    SELECT COUNT(*) INTO has_manual
    FROM `proc_assessment_questions` aq
             JOIN `proc_questions` q ON aq.question_id = q.question_id
    WHERE aq.assessment_id = NEW.assessment_id
      AND q.question_type IN ('long_answer', 'file_upload');

    UPDATE `proc_assessments`
    SET `require_manual_grading` = IF(has_manual > 0, 1, 0)
    WHERE `assessment_id` = NEW.`assessment_id`;
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `trg_aq_delete` AFTER DELETE ON `proc_assessment_questions` FOR EACH ROW BEGIN
    UPDATE `proc_assessments`
    SET `total_questions` = (
        SELECT COUNT(*) FROM `proc_assessment_questions` WHERE `assessment_id` = OLD.`assessment_id`
    ),
        `total_points` = (
            SELECT COALESCE(SUM(COALESCE(aq.points_override, q.points)), 0)
            FROM `proc_assessment_questions` aq
                     JOIN `proc_questions` q ON aq.question_id = q.question_id
            WHERE aq.assessment_id = OLD.assessment_id
        )
    WHERE `assessment_id` = OLD.`assessment_id`;

    IF OLD.`section_id` IS NOT NULL THEN
        UPDATE `proc_assessment_sections`
        SET `question_count` = (
            SELECT COUNT(*) FROM `proc_assessment_questions` WHERE `section_id` = OLD.`section_id`
        ),
            `total_points` = (
                SELECT COALESCE(SUM(COALESCE(aq.points_override, q.points)), 0)
                FROM `proc_assessment_questions` aq
                         JOIN `proc_questions` q ON aq.question_id = q.question_id
                WHERE aq.section_id = OLD.section_id
            )
        WHERE `section_id` = OLD.`section_id`;
    END IF;
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `trg_aq_insert` AFTER INSERT ON `proc_assessment_questions` FOR EACH ROW BEGIN
    UPDATE `proc_assessments`
    SET `total_questions` = (
        SELECT COUNT(*) FROM `proc_assessment_questions` WHERE `assessment_id` = NEW.`assessment_id`
    ),
        `total_points` = (
            SELECT COALESCE(SUM(COALESCE(aq.points_override, q.points)), 0)
            FROM `proc_assessment_questions` aq
                     JOIN `proc_questions` q ON aq.question_id = q.question_id
            WHERE aq.assessment_id = NEW.assessment_id
        )
    WHERE `assessment_id` = NEW.`assessment_id`;

    -- Update section count if applicable
    IF NEW.`section_id` IS NOT NULL THEN
        UPDATE `proc_assessment_sections`
        SET `question_count` = (
            SELECT COUNT(*) FROM `proc_assessment_questions` WHERE `section_id` = NEW.`section_id`
        ),
            `total_points` = (
                SELECT COALESCE(SUM(COALESCE(aq.points_override, q.points)), 0)
                FROM `proc_assessment_questions` aq
                         JOIN `proc_questions` q ON aq.question_id = q.question_id
                WHERE aq.section_id = NEW.section_id
            )
        WHERE `section_id` = NEW.`section_id`;
    END IF;
END
$$
DELIMITER ;

