--
-- Triggers `proc_attempts`
--
DELIMITER $$
CREATE TRIGGER `trg_add_to_grading_queue` AFTER UPDATE ON `proc_attempts` FOR EACH ROW BEGIN
    IF NEW.`status` IN ('submitted', 'auto_submitted') AND OLD.`status` = 'in_progress' THEN
        INSERT INTO `proc_grading_queue` (
            `tenant_id`, `answer_id`, `attempt_id`, `assessment_id`, `question_id`, `user_id`,
            `question_type`, `question_text`, `max_points`, `status`, `created_at`
        )
        SELECT aa.`tenant_id`, aa.`answer_id`, aa.`attempt_id`, a.`assessment_id`, aa.`question_id`, NEW.`user_id`,
               aa.`question_type`, aa.`question_text_snapshot`, aa.`max_points`, 'pending', NOW()
        FROM `proc_attempt_answers` aa
                 JOIN `proc_attempts` a ON aa.`attempt_id` = a.`attempt_id`
        WHERE aa.`attempt_id` = NEW.`attempt_id`
          AND aa.`question_type` IN ('long_answer', 'file_upload')
          AND aa.`is_answered` = 1
        ON DUPLICATE KEY UPDATE `status` = 'pending';
    END IF;
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `trg_attempt_insert` AFTER INSERT ON `proc_attempts` FOR EACH ROW BEGIN
    INSERT INTO `proc_learner_assessments`
    (`tenant_id`, `user_id`, `assessment_id`, `status`, `total_attempts`, `first_attempted_at`, `last_attempted_at`, `last_attempt_id`, `created_at`)
    VALUES
        (NEW.`tenant_id`, NEW.`user_id`, NEW.`assessment_id`, 'in_progress', 1, NOW(), NOW(), NEW.`attempt_id`, NOW())
    ON DUPLICATE KEY UPDATE
                         `total_attempts` = `total_attempts` + 1,
                         `last_attempted_at` = NOW(),
                         `last_attempt_id` = NEW.`attempt_id`,
                         `status` = 'in_progress';
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `trg_attempt_update` AFTER UPDATE ON `proc_attempts` FOR EACH ROW BEGIN
    IF NEW.`status` = 'graded' AND OLD.`status` != 'graded' THEN
        UPDATE `proc_learner_assessments` la
        SET
            `last_score` = NEW.`percentage_score`,
            `best_score` = GREATEST(COALESCE(`best_score`, 0), NEW.`percentage_score`),
            `status` = IF(NEW.`passed` = 1, 'passed', 'failed'),
            `completed_at` = IF(NEW.`passed` = 1, NOW(), `completed_at`),
            `best_attempt_id` = IF(
                    NEW.`percentage_score` > COALESCE(`best_score`, 0),
                    NEW.`attempt_id`,
                    `best_attempt_id`
                                )
        WHERE `user_id` = NEW.`user_id` AND `assessment_id` = NEW.`assessment_id`;
    END IF;
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `trg_auto_issue_certificate` AFTER UPDATE ON `proc_attempts` FOR EACH ROW BEGIN
    DECLARE v_template_id BIGINT;
    DECLARE v_auto_issue TINYINT;
    DECLARE v_min_score DECIMAL(5,2);
    DECLARE v_require_pass TINYINT;
    DECLARE v_cert_exists INT;

    -- Check if status changed to 'graded' and passed
    IF NEW.`status` = 'graded' AND OLD.`status` != 'graded' THEN
        -- Get certificate settings for this assessment
        SELECT ac.`template_id`, ac.`auto_issue`, ac.`min_score`, ac.`require_pass`
        INTO v_template_id, v_auto_issue, v_min_score, v_require_pass
        FROM `proc_assessment_certificates` ac
        WHERE ac.`assessment_id` = NEW.`assessment_id`
        LIMIT 1;

        -- Check if auto-issue is enabled and conditions are met
        IF v_auto_issue = 1 AND v_template_id IS NOT NULL THEN
            -- Check pass requirement
            IF (v_require_pass = 0 OR NEW.`passed` = 1) THEN
                -- Check minimum score requirement
                IF (v_min_score IS NULL OR NEW.`percentage_score` >= v_min_score) THEN
                    -- Check if certificate already exists
                    SELECT COUNT(*) INTO v_cert_exists
                    FROM `proc_certificates`
                    WHERE `attempt_id` = NEW.`attempt_id`;

                    -- Mark for certificate issuance (actual issuance done via application)
                    IF v_cert_exists = 0 THEN
                        UPDATE `proc_learner_assessments`
                        SET `certificate_issued` = 0
                        WHERE `user_id` = NEW.`user_id` AND `assessment_id` = NEW.`assessment_id`;
                    END IF;
                END IF;
            END IF;
        END IF;
    END IF;
END
$$
DELIMITER ;

