--
-- Table structure for table `proc_attempt_answers`
--

CREATE TABLE `proc_attempt_answers` (
  `answer_id` bigint(20) UNSIGNED NOT NULL,
  `attempt_id` bigint(20) UNSIGNED NOT NULL,
  `question_id` bigint(20) UNSIGNED NOT NULL,
  `tenant_id` bigint(20) UNSIGNED NOT NULL,
  `question_type` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `question_text_snapshot` text COLLATE utf8mb4_unicode_ci,
  `max_points` decimal(10,2) NOT NULL,
  `answer_data` json DEFAULT NULL COMMENT 'Flexible answer storage',
  `is_correct` tinyint(1) DEFAULT NULL COMMENT 'NULL=not graded, 0=wrong, 1=correct',
  `is_partial` tinyint(1) DEFAULT '0',
  `points_earned` decimal(10,2) DEFAULT '0.00',
  `auto_graded` tinyint(1) DEFAULT '0',
  `manually_graded` tinyint(1) DEFAULT '0',
  `graded_by` bigint(20) DEFAULT NULL,
  `graded_at` datetime DEFAULT NULL,
  `grader_feedback` text COLLATE utf8mb4_unicode_ci,
  `time_spent_seconds` int(11) DEFAULT '0',
  `first_viewed_at` datetime DEFAULT NULL,
  `first_answered_at` datetime DEFAULT NULL,
  `last_modified_at` datetime DEFAULT NULL,
  `answer_changes` int(11) DEFAULT '0' COMMENT 'Number of times answer was changed',
  `is_answered` tinyint(1) DEFAULT '0',
  `is_skipped` tinyint(1) DEFAULT '0',
  `marked_for_review` tinyint(1) DEFAULT '0',
  `confidence_level` enum('low','medium','high') COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

--
-- Triggers `proc_attempt_answers`
--
DELIMITER $$
CREATE TRIGGER `trg_answer_insert` AFTER INSERT ON `proc_attempt_answers` FOR EACH ROW BEGIN
    IF NEW.`is_answered` = 1 THEN
        UPDATE `proc_attempts`
        SET `answered_questions` = `answered_questions` + 1
        WHERE `attempt_id` = NEW.`attempt_id`;
    END IF;
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `trg_answer_update` AFTER UPDATE ON `proc_attempt_answers` FOR EACH ROW BEGIN
    -- Update answered count
    IF NEW.`is_answered` = 1 AND OLD.`is_answered` = 0 THEN
        UPDATE `proc_attempts`
        SET `answered_questions` = `answered_questions` + 1
        WHERE `attempt_id` = NEW.`attempt_id`;
    ELSEIF NEW.`is_answered` = 0 AND OLD.`is_answered` = 1 THEN
        UPDATE `proc_attempts`
        SET `answered_questions` = GREATEST(0, `answered_questions` - 1)
        WHERE `attempt_id` = NEW.`attempt_id`;
    END IF;
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `trg_grading_history` AFTER UPDATE ON `proc_attempt_answers` FOR EACH ROW BEGIN
    IF NEW.`points_earned` != OLD.`points_earned` OR
       (NEW.`manually_graded` = 1 AND OLD.`manually_graded` = 0) THEN
        INSERT INTO `proc_grading_history` (
            `answer_id`, `tenant_id`, `action`, `previous_score`, `new_score`, `performed_by`, `performed_at`
        ) VALUES (NEW.`answer_id`, NEW.`tenant_id`, IF(OLD.`manually_graded` = 0, 'graded', 'score_changed'),
                  OLD.`points_earned`, NEW.`points_earned`, NEW.`graded_by`, NOW());
    END IF;
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `trg_manual_grade_update` AFTER UPDATE ON `proc_attempt_answers` FOR EACH ROW BEGIN
    IF NEW.`manually_graded` = 1 AND OLD.`manually_graded` = 0 THEN
        UPDATE `proc_attempts`
        SET `graded_questions` = `graded_questions` + 1,
            `pending_grading` = GREATEST(0, `pending_grading` - 1)
        WHERE `attempt_id` = NEW.`attempt_id`;
    END IF;
END
$$
DELIMITER ;

