  `audio_recording_path` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `flagged_for_review` tinyint(1) DEFAULT '0',
  `flagged_reason` text COLLATE utf8mb4_unicode_ci,
