--
-- Triggers `proc_proctoring_sessions`
--
DELIMITER $$
CREATE TRIGGER `trg_session_flag_check` BEFORE UPDATE ON `proc_proctoring_sessions` FOR EACH ROW BEGIN
    IF NEW.`trust_score` < 50 AND OLD.`trust_score` >= 50 AND NEW.`flagged_for_review` = 0 THEN
        SET NEW.`flagged_for_review` = 1;
        SET NEW.`flagged_reason` = CONCAT('Trust score dropped to ', NEW.`trust_score`);
    END IF;
END
$$
DELIMITER ;

