  `face_count` int(11) DEFAULT NULL,
  `face_confidence` decimal(3,2) DEFAULT NULL,
  `face_position` json DEFAULT NULL COMMENT '{"x": 100, "y": 50, "width": 200, "height": 250}',
  `gaze_direction` json DEFAULT NULL COMMENT '{"x": 0.1, "y": -0.2}',
  `emotion_detected` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `objects_detected` json DEFAULT NULL COMMENT '["phone", "book"]',
  `flagged` tinyint(1) DEFAULT '0',
  `flag_reason` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `captured_at` datetime(3) DEFAULT CURRENT_TIMESTAMP(3)
