DELIMITER $$
CREATE TRIGGER `trg_snapshot_insert` AFTER INSERT ON `proc_proctoring_snapshots` FOR EACH ROW BEGIN
    UPDATE `proc_proctoring_sessions`
    SET `total_snapshots` = `total_snapshots` + 1
    WHERE `session_id` = NEW.`session_id`;
END
