--
-- Table structure for table `proc_proctoring_violations`
--

CREATE TABLE `proc_proctoring_violations` (
  `violation_id` bigint(20) UNSIGNED NOT NULL,
  `session_id` bigint(20) UNSIGNED NOT NULL,
  `attempt_id` bigint(20) UNSIGNED NOT NULL,
  `tenant_id` bigint(20) UNSIGNED NOT NULL,
  `violation_type` enum('tab_switch','window_blur','fullscreen_exit','copy_attempt','paste_attempt','right_click','print_screen','dev_tools_open','browser_resize','no_face_detected','multiple_faces','face_not_centered','face_too_far','face_too_close','face_obscured','different_person','voice_detected','multiple_voices','excessive_noise','phone_detected','book_detected','another_screen','suspicious_object','looking_away','suspicious_movement','idle_timeout','rapid_answers','connection_lost','vpn_detected','proxy_detected','manual_flag','ai_anomaly','other') COLLATE utf8mb4_unicode_ci NOT NULL,
  `severity` enum('low','medium','high','critical') COLLATE utf8mb4_unicode_ci DEFAULT 'medium',
  `violation_score` decimal(5,2) DEFAULT '1.00' COMMENT 'Weight for trust score',
  `description` text COLLATE utf8mb4_unicode_ci,
  `question_id` bigint(20) UNSIGNED DEFAULT NULL,
  `question_index` int(11) DEFAULT NULL,
  `snapshot_path` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `video_clip_path` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `audio_clip_path` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `event_data` json DEFAULT NULL COMMENT 'Additional violation details',
  `action_taken` enum('none','warning_shown','paused','auto_submitted','terminated') COLLATE utf8mb4_unicode_ci DEFAULT 'none',
  `user_acknowledged` tinyint(1) DEFAULT '0',
  `acknowledged_at` datetime DEFAULT NULL,
  `reviewed` tinyint(1) DEFAULT '0',
  `reviewed_by` bigint(20) DEFAULT NULL,
  `reviewed_at` datetime DEFAULT NULL,
  `review_status` enum('pending','valid','false_positive','inconclusive') COLLATE utf8mb4_unicode_ci DEFAULT 'pending',
  `review_notes` text COLLATE utf8mb4_unicode_ci,
  `timestamp` datetime(3) DEFAULT CURRENT_TIMESTAMP(3)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

--
-- Triggers `proc_proctoring_violations`
--
DELIMITER $$
CREATE TRIGGER `trg_violation_insert` AFTER INSERT ON `proc_proctoring_violations` FOR EACH ROW BEGIN
    -- Update session violation count and trust score
    UPDATE `proc_proctoring_sessions`
    SET
        `total_violations` = `total_violations` + 1,
        `violation_score` = `violation_score` + NEW.`violation_score`,
        `trust_score` = GREATEST(0, `trust_score` - NEW.`violation_score`)
    WHERE `session_id` = NEW.`session_id`;

    -- Update specific counters
    IF NEW.`violation_type` = 'tab_switch' THEN
        UPDATE `proc_proctoring_sessions` SET `tab_switch_count` = `tab_switch_count` + 1 WHERE `session_id` = NEW.`session_id`;
    ELSEIF NEW.`violation_type` = 'window_blur' THEN
        UPDATE `proc_proctoring_sessions` SET `window_blur_count` = `window_blur_count` + 1 WHERE `session_id` = NEW.`session_id`;
    ELSEIF NEW.`violation_type` = 'fullscreen_exit' THEN
        UPDATE `proc_proctoring_sessions` SET `fullscreen_exit_count` = `fullscreen_exit_count` + 1 WHERE `session_id` = NEW.`session_id`;
    ELSEIF NEW.`violation_type` = 'no_face_detected' THEN
        UPDATE `proc_proctoring_sessions` SET `no_face_detected_count` = `no_face_detected_count` + 1 WHERE `session_id` = NEW.`session_id`;
    ELSEIF NEW.`violation_type` = 'multiple_faces' THEN
        UPDATE `proc_proctoring_sessions` SET `multiple_faces_detected_count` = `multiple_faces_detected_count` + 1 WHERE `session_id` = NEW.`session_id`;
    END IF;

    -- Update attempt proctoring score and flag
    UPDATE `proc_attempts`
    SET
        `violation_count` = `violation_count` + 1,
        `proctoring_score` = (SELECT `trust_score` FROM `proc_proctoring_sessions` WHERE `session_id` = NEW.`session_id`)
    WHERE `attempt_id` = NEW.`attempt_id`;
END
$$
DELIMITER ;

