--
-- Table structure for table `proc_questions`
--

CREATE TABLE `proc_questions` (
  `question_id` bigint(20) UNSIGNED NOT NULL,
  `tenant_id` bigint(20) UNSIGNED NOT NULL,
  `bank_id` bigint(20) UNSIGNED NOT NULL,
  `category_id` bigint(20) UNSIGNED DEFAULT NULL,
  `question_type` enum('multiple_choice_single','multiple_choice_multiple','true_false','fill_in_blanks','short_answer','long_answer','matching','ordering','hotspot','numeric','file_upload') COLLATE utf8mb4_unicode_ci NOT NULL,
  `question_text` longtext COLLATE utf8mb4_unicode_ci NOT NULL,
  `question_html` longtext COLLATE utf8mb4_unicode_ci COMMENT 'Rich text version',
  `explanation` text COLLATE utf8mb4_unicode_ci COMMENT 'Shown after answering',
  `hint` text COLLATE utf8mb4_unicode_ci COMMENT 'Optional hint for learners',
  `featured_image` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Full path: uploads/tenant_{id}/assessment/...',
  `audio_url` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `video_url` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `points` decimal(10,2) DEFAULT '1.00',
  `negative_points` decimal(10,2) DEFAULT '0.00' COMMENT 'Deducted for wrong answer',
  `partial_credit` tinyint(1) DEFAULT '0' COMMENT 'Allow partial scoring',
  `difficulty` enum('easy','medium','hard') COLLATE utf8mb4_unicode_ci DEFAULT 'medium',
  `estimated_time_seconds` int(11) DEFAULT '60',
  `case_sensitive` tinyint(1) DEFAULT '0' COMMENT 'For fill_in_blanks, short_answer',
  `allow_regex` tinyint(1) DEFAULT '0' COMMENT 'For short_answer validation',
  `numeric_tolerance` decimal(10,4) DEFAULT '0.0000' COMMENT 'For numeric questions',
  `max_file_size_mb` int(11) DEFAULT '10' COMMENT 'For file_upload',
  `allowed_file_types` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT 'pdf,doc,docx,jpg,png' COMMENT 'For file_upload',
  `max_words` int(11) DEFAULT NULL COMMENT 'For long_answer',
  `min_words` int(11) DEFAULT NULL COMMENT 'For long_answer',
  `version` int(11) DEFAULT '1',
  `status` enum('draft','active','archived') COLLATE utf8mb4_unicode_ci DEFAULT 'active',
  `usage_count` int(11) DEFAULT '0' COMMENT 'Times used in assessments',
  `avg_score` decimal(5,2) DEFAULT NULL COMMENT 'Average score percentage',
  `times_answered` int(11) DEFAULT '0',
  `times_correct` int(11) DEFAULT '0',
  `created_by` bigint(20) DEFAULT NULL,
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

--
-- Triggers `proc_questions`
--
DELIMITER $$
CREATE TRIGGER `trg_question_delete` AFTER DELETE ON `proc_questions` FOR EACH ROW BEGIN
    UPDATE `proc_question_banks` SET `total_questions` = `total_questions` - 1 WHERE `bank_id` = OLD.`bank_id`;
    IF OLD.`category_id` IS NOT NULL THEN
        UPDATE `proc_question_categories` SET `question_count` = `question_count` - 1 WHERE `category_id` = OLD.`category_id`;
    END IF;
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `trg_question_insert` AFTER INSERT ON `proc_questions` FOR EACH ROW BEGIN
    UPDATE `proc_question_banks` SET `total_questions` = `total_questions` + 1 WHERE `bank_id` = NEW.`bank_id`;
    IF NEW.`category_id` IS NOT NULL THEN
        UPDATE `proc_question_categories` SET `question_count` = `question_count` + 1 WHERE `category_id` = NEW.`category_id`;
    END IF;
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `trg_question_update` AFTER UPDATE ON `proc_questions` FOR EACH ROW BEGIN
    -- Handle bank change
    IF OLD.bank_id <> NEW.bank_id THEN
        UPDATE proc_question_banks
        SET total_questions = total_questions - 1
        WHERE bank_id = OLD.bank_id;

        UPDATE proc_question_banks
        SET total_questions = total_questions + 1
        WHERE bank_id = NEW.bank_id;
    END IF;

    -- Handle category change (NULL-safe comparison)
    IF NOT (OLD.category_id <=> NEW.category_id) THEN

        IF OLD.category_id IS NOT NULL THEN
            UPDATE proc_question_categories
            SET question_count = question_count - 1
            WHERE category_id = OLD.category_id;
        END IF;

        IF NEW.category_id IS NOT NULL THEN
            UPDATE proc_question_categories
            SET question_count = question_count + 1
            WHERE category_id = NEW.category_id;
        END IF;

    END IF;
END
$$
DELIMITER ;

