--
-- Table structure for table `role_skills`
--

CREATE TABLE `role_skills` (
  `id` int(11) NOT NULL,
  `role_id` bigint(20) NOT NULL COMMENT 'FK to roles/designations table',
  `skill_id` bigint(20) NOT NULL,
  `proficiency_level` enum('awareness','basic','intermediate','advanced','expert') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'basic',
  `is_required` tinyint(1) NOT NULL DEFAULT '1' COMMENT '1=mandatory, 0=nice-to-have',
  `priority` enum('critical','high','medium','low') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'medium',
  `tenant_id` bigint(20) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

