--
-- Table structure for table `scheduled_reports`
--

CREATE TABLE `scheduled_reports` (
  `id` int(11) NOT NULL,
  `user_id` int(11) NOT NULL,
  `tenant_id` int(11) NOT NULL,
  `report_key` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `frequency` enum('daily','weekly','monthly') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'weekly',
  `recipients` text COLLATE utf8mb4_unicode_ci COMMENT 'Comma-separated emails',
  `params` json DEFAULT NULL COMMENT 'Report filter parameters',
  `export_format` enum('csv','xlsx','pdf') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'csv',
  `day_of_week` tinyint(4) DEFAULT '1' COMMENT '1=Mon..7=Sun (for weekly)',
  `day_of_month` tinyint(4) DEFAULT '1' COMMENT '1-28 (for monthly)',
  `time_of_day` varchar(5) COLLATE utf8mb4_unicode_ci DEFAULT '08:00' COMMENT 'HH:MM format',
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `last_run_at` datetime DEFAULT NULL,
  `next_run_at` datetime DEFAULT NULL,
  `last_run_status` enum('success','error','pending') COLLATE utf8mb4_unicode_ci DEFAULT 'pending',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

