DROP TABLE IF EXISTS `media_version_history`;

CREATE ALGORITHM=UNDEFINED DEFINER=`central_lxp`@`%` SQL SECURITY DEFINER VIEW `media_version_history`  AS SELECT `m`.`media_id` AS `media_id`, `m`.`tenant_id` AS `tenant_id`, coalesce(`m`.`root_parent_id`,`m`.`media_id`) AS `root_media_id`, `m`.`title` AS `title`, `m`.`media_type` AS `media_type`, `m`.`version_number` AS `version_number`, `m`.`version_label` AS `version_label`, `m`.`version_notes` AS `version_notes`, `m`.`is_latest_version` AS `is_latest_version`, `m`.`file_size` AS `file_size`, `m`.`file_url` AS `file_url`, `m`.`uploaded_by` AS `uploaded_by`, `u`.`first_name` AS `uploader_first_name`, `u`.`last_name` AS `uploader_last_name`, `m`.`created_at` AS `uploaded_at` FROM (`media` `m` left join `users` `u` on((`m`.`uploaded_by` = `u`.`id`))) WHERE (`m`.`is_active` = 1) ORDER BY coalesce(`m`.`root_parent_id`,`m`.`media_id`) ASC, `m`.`version_number` DESC ;

