--
-- Structure for view `vw_course_engagement`
--
DROP TABLE IF EXISTS `vw_course_engagement`;

CREATE ALGORITHM=UNDEFINED DEFINER=`central_lxp`@`%` SQL SECURITY DEFINER VIEW `vw_course_engagement`  AS SELECT `c`.`course_id` AS `course_id`, `c`.`tenant_id` AS `tenant_id`, `c`.`title` AS `course_title`, count(distinct `ce`.`user_id`) AS `enrolled_learners`, count(distinct (case when (`ce`.`status` = 'completed') then `ce`.`user_id` end)) AS `completed_learners`, avg(`ce`.`progress_percentage`) AS `avg_progress`, sum(`ce`.`time_spent_minutes`) AS `total_learning_minutes`, `c`.`average_rating` AS `average_rating`, `c`.`rating_count` AS `rating_count` FROM (`courses` `c` left join `course_enrollments` `ce` on(((`c`.`course_id` = `ce`.`course_id`) and (`ce`.`is_active` = 1)))) WHERE (`c`.`is_active` = 1) GROUP BY `c`.`course_id`, `c`.`tenant_id`, `c`.`title`, `c`.`average_rating`, `c`.`rating_count` ;

