--
-- Structure for view `vw_daily_learning_activity`
--
DROP TABLE IF EXISTS `vw_daily_learning_activity`;

CREATE ALGORITHM=UNDEFINED DEFINER=`central_lxp`@`%` SQL SECURITY DEFINER VIEW `vw_daily_learning_activity`  AS SELECT cast(`ls`.`started_at` as date) AS `activity_date`, `ls`.`tenant_id` AS `tenant_id`, count(distinct `ls`.`user_id`) AS `unique_learners`, count(`ls`.`session_id`) AS `total_sessions`, sum(`ls`.`time_spent_minutes`) AS `total_minutes`, avg(`ls`.`time_spent_minutes`) AS `avg_session_minutes`, sum(`ls`.`pages_viewed`) AS `total_pages_viewed` FROM `learning_sessions` AS `ls` WHERE (`ls`.`ended_at` is not null) GROUP BY cast(`ls`.`started_at` as date), `ls`.`tenant_id` ;

