--
-- Structure for view `vw_learning_path_stats`
--
DROP TABLE IF EXISTS `vw_learning_path_stats`;

CREATE ALGORITHM=UNDEFINED DEFINER=`central_lxp`@`%` SQL SECURITY DEFINER VIEW `vw_learning_path_stats`  AS SELECT `lp`.`path_id` AS `path_id`, `lp`.`tenant_id` AS `tenant_id`, `lp`.`title` AS `title`, `lp`.`status` AS `status`, count(distinct `lpe`.`enrollment_id`) AS `total_enrollments`, count(distinct (case when (`lpe`.`status` = 'active') then `lpe`.`enrollment_id` end)) AS `active_enrollments`, count(distinct (case when (`lpe`.`status` = 'completed') then `lpe`.`enrollment_id` end)) AS `completed_enrollments`, round(avg(`lpe`.`progress_percentage`),2) AS `avg_progress`, round(avg((case when (`lpe`.`status` = 'completed') then (to_days(`lpe`.`completed_at`) - to_days(`lpe`.`enrolled_at`)) end)),1) AS `avg_completion_days`, round(avg(`lpr`.`rating`),2) AS `avg_rating`, count(distinct `lpr`.`review_id`) AS `total_reviews` FROM ((`learning_paths` `lp` left join `learning_path_enrollments` `lpe` on(((`lp`.`path_id` = `lpe`.`path_id`) and (`lpe`.`is_active` = 1)))) left join `learning_path_reviews` `lpr` on(((`lp`.`path_id` = `lpr`.`path_id`) and (`lpr`.`status` = 'approved')))) WHERE (`lp`.`is_active` = 1) GROUP BY `lp`.`path_id`, `lp`.`tenant_id`, `lp`.`title`, `lp`.`status` ;

