--
-- Structure for view `vw_lesson_completion_stats`
--
DROP TABLE IF EXISTS `vw_lesson_completion_stats`;

CREATE ALGORITHM=UNDEFINED DEFINER=`central_lxp`@`%` SQL SECURITY DEFINER VIEW `vw_lesson_completion_stats`  AS SELECT `l`.`lesson_id` AS `lesson_id`, `l`.`course_id` AS `course_id`, `l`.`title` AS `lesson_title`, `l`.`content_type` AS `content_type`, count(distinct `lp`.`user_id`) AS `started_count`, count(distinct (case when (`lp`.`status` = 'completed') then `lp`.`user_id` end)) AS `completed_count`, avg(`lp`.`time_spent_seconds`) AS `avg_time_seconds`, avg(`lp`.`score`) AS `avg_score`, avg(`lp`.`attempts`) AS `avg_attempts` FROM (`lessons` `l` left join `lesson_progress` `lp` on((`l`.`lesson_id` = `lp`.`lesson_id`))) WHERE (`l`.`is_active` = 1) GROUP BY `l`.`lesson_id`, `l`.`course_id`, `l`.`title`, `l`.`content_type` ;

