--
-- Structure for view `vw_live_training_summary`
--
DROP TABLE IF EXISTS `vw_live_training_summary`;

CREATE ALGORITHM=UNDEFINED DEFINER=`central_lxp`@`%` SQL SECURITY DEFINER VIEW `vw_live_training_summary`  AS SELECT `lt`.`training_id` AS `training_id`, `lt`.`tenant_id` AS `tenant_id`, `lt`.`title` AS `title`, `lt`.`training_type` AS `training_type`, `lt`.`status` AS `status`, count(distinct `lts`.`session_id`) AS `total_sessions`, count(distinct (case when (`lts`.`status` = 'completed') then `lts`.`session_id` end)) AS `completed_sessions`, count(distinct `lte`.`enrollment_id`) AS `total_enrollments`, count(distinct (case when (`lte`.`status` = 'enrolled') then `lte`.`enrollment_id` end)) AS `active_enrollments`, count(distinct (case when (`lte`.`certification_status` = 'issued') then `lte`.`enrollment_id` end)) AS `certificates_issued`, min(`lts`.`session_date`) AS `first_session_date`, max(`lts`.`session_date`) AS `last_session_date` FROM ((`live_trainings` `lt` left join `live_training_sessions` `lts` on((`lt`.`training_id` = `lts`.`training_id`))) left join `live_training_enrollments` `lte` on((`lt`.`training_id` = `lte`.`training_id`))) GROUP BY `lt`.`training_id` ;

