--
-- Structure for view `vw_session_attendance_summary`
--
DROP TABLE IF EXISTS `vw_session_attendance_summary`;

CREATE ALGORITHM=UNDEFINED DEFINER=`central_lxp`@`%` SQL SECURITY DEFINER VIEW `vw_session_attendance_summary`  AS SELECT `lts`.`session_id` AS `session_id`, `lts`.`training_id` AS `training_id`, `lts`.`tenant_id` AS `tenant_id`, `lts`.`title` AS `session_title`, `lts`.`session_date` AS `session_date`, `lts`.`session_type` AS `session_type`, `lts`.`status` AS `session_status`, count(distinct `lte`.`enrollment_id`) AS `expected_attendees`, count(distinct (case when (`lta`.`status` = 'present') then `lta`.`user_id` end)) AS `present_count`, count(distinct (case when (`lta`.`status` = 'late') then `lta`.`user_id` end)) AS `late_count`, count(distinct (case when ((`lta`.`status` = 'absent') or isnull(`lta`.`status`)) then `lte`.`user_id` end)) AS `absent_count`, count(distinct (case when (`lta`.`attendance_mode` = 'physical') then `lta`.`user_id` end)) AS `physical_attendees`, count(distinct (case when (`lta`.`attendance_mode` = 'virtual') then `lta`.`user_id` end)) AS `virtual_attendees`, round(((count(distinct (case when (`lta`.`status` in ('present','late')) then `lta`.`user_id` end)) * 100.0) / nullif(count(distinct `lte`.`enrollment_id`),0)),2) AS `attendance_percentage` FROM ((`live_training_sessions` `lts` left join `live_training_enrollments` `lte` on(((`lts`.`training_id` = `lte`.`training_id`) and (`lte`.`status` = 'enrolled')))) left join `live_training_attendance` `lta` on(((`lts`.`session_id` = `lta`.`session_id`) and (`lte`.`user_id` = `lta`.`user_id`)))) GROUP BY `lts`.`session_id` ;

