CREATE ALGORITHM=UNDEFINED DEFINER=`central_lxp`@`%` SQL SECURITY DEFINER VIEW `vw_unread_mentions`  AS SELECT `mm`.`mentioned_user_id` AS `user_id`, `mm`.`tenant_id` AS `tenant_id`, count(0) AS `unread_mention_count`, max(`m`.`created_at`) AS `latest_mention_at` FROM (`message_mentions` `mm` join `messages` `m` on((`mm`.`message_id` = `m`.`message_id`))) WHERE ((`mm`.`is_read` = 0) AND (`m`.`is_deleted` = 0)) GROUP BY `mm`.`mentioned_user_id`, `mm`.`tenant_id` ;

