DROP TABLE IF EXISTS `vw_user_path_progress`;

CREATE ALGORITHM=UNDEFINED DEFINER=`central_lxp`@`%` SQL SECURITY DEFINER VIEW `vw_user_path_progress`  AS SELECT `lpe`.`enrollment_id` AS `enrollment_id`, `lpe`.`path_id` AS `path_id`, `lpe`.`user_id` AS `user_id`, `lpe`.`tenant_id` AS `tenant_id`, `lp`.`title` AS `path_title`, `lpe`.`status` AS `status`, `lpe`.`progress_percentage` AS `progress_percentage`, `lpe`.`items_completed` AS `items_completed`, `lpe`.`items_total` AS `items_total`, `lpe`.`total_time_spent_minutes` AS `total_time_spent_minutes`, `lpe`.`enrolled_at` AS `enrolled_at`, `lpe`.`started_at` AS `started_at`, `lpe`.`completed_at` AS `completed_at`, `lpe`.`due_date` AS `due_date`, (case when ((`lpe`.`due_date` is not null) and (`lpe`.`due_date` < curdate()) and (`lpe`.`status` <> 'completed')) then 1 else 0 end) AS `is_overdue`, (to_days(`lpe`.`due_date`) - to_days(curdate())) AS `days_until_due` FROM (`learning_path_enrollments` `lpe` join `learning_paths` `lp` on((`lpe`.`path_id` = `lp`.`path_id`))) WHERE (`lpe`.`is_active` = 1) ;

