DROP TABLE IF EXISTS `v_training_enrollment_stats`;

CREATE ALGORITHM=UNDEFINED DEFINER=`central_lxp`@`%` SQL SECURITY DEFINER VIEW `v_training_enrollment_stats`  AS SELECT `lt`.`training_id` AS `training_id`, `lt`.`title` AS `title`, `lt`.`tenant_id` AS `tenant_id`, count(distinct `lte`.`enrollment_id`) AS `total_enrollments`, sum((case when (`lte`.`enrollment_method` = 'manual') then 1 else 0 end)) AS `manual_enrollments`, sum((case when (`lte`.`enrollment_method` = 'rule_based') then 1 else 0 end)) AS `rule_based_enrollments`, sum((case when (`lte`.`enrollment_method` = 'automatic') then 1 else 0 end)) AS `automatic_enrollments`, sum((case when (`lte`.`enrollment_method` = 'self_enrollment') then 1 else 0 end)) AS `self_enrollments`, sum((case when (`lte`.`status` = 'completed') then 1 else 0 end)) AS `completed_count` FROM (`live_trainings` `lt` left join `live_training_enrollments` `lte` on((`lt`.`training_id` = `lte`.`training_id`))) GROUP BY `lt`.`training_id`, `lt`.`title`, `lt`.`tenant_id` ;

