DELIMITER $$
--
-- Events
--
CREATE DEFINER=`central_lxp`@`%` EVENT `evt_expire_certificates` ON SCHEDULE EVERY 1 DAY STARTS '2026-02-01 23:12:25' ON COMPLETION NOT PRESERVE ENABLE DO BEGIN
        UPDATE `proc_certificates`
        SET `status` = 'expired', `expired` = 1
        WHERE `valid_until` IS NOT NULL
          AND `valid_until` < CURDATE()
          AND `status` = 'active';
    END$$

DELIMITER ;
COMMIT;

